<?php require_once __DIR__.'/../includes/auth.php'; require_role(['admin']); $pageTitle='Status History'; require __DIR__.'/../includes/header.php'; $rows=$pdo->query('SELECT h.*,r.item_name,u.full_name FROM status_history h JOIN item_reports r ON r.id=h.item_report_id LEFT JOIN users u ON u.id=h.changed_by ORDER BY h.changed_at DESC LIMIT 200')->fetchAll();echo '<h1>Item status history</h1><div class="table-wrap"><table><tr><th>Item</th><th>From</th><th>To</th><th>Changed by</th><th>When</th><th>Notes</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['item_name']).'</td><td>'.e($r['old_status']??'—').'</td><td>'.e($r['new_status']).'</td><td>'.e($r['full_name']??'System').'</td><td>'.e($r['changed_at']).'</td><td>'.e($r['notes']).'</td></tr>';}echo '</table></div>'; require __DIR__.'/../includes/footer.php'; ?>